    it.todo("a policy covering a sword and 3 runes → insurance sum 1750 G (block discount does not affect the sum)");
    it.todo("sword policy (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G");
    it.todo("sword policy, second claim of 1500 G → payout 600 G, remainingCap 0 G (reduced to remaining cap)");
  });

  describe("claim — rounding in the MHPCO's favor", () => {
    it.todo("a payout calculation yielding 350.5 G → final payout 350 G (rounded down)");
  });

  describe("errors", () => {
    it.todo("quote with an item of unknown type (e.g. broomstick) → error");
    it.todo("claim referencing an item that is not part of the policy → error");
    it.todo("claim referencing a damage item with an unknown type → error");
