import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  describe("quote — base premiums", () => {
    it("empty item list → premium 5 G (processing fee only)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [] }],
      });

      expect(result).toEqual({ results: [{ premium: 5 }] });
    });
    it("a single sword → premium 115 G (100 base + 10 first insurance + 5 fee)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [
          {
            op: "quote",
            items: [{ type: "sword", material: "steel", enchantment: 3, cursed: false }],
          },
        ],
      });

      expect(result).toEqual({ results: [{ premium: 115 }] });
    });
    it("a single amulet → base premium 60 G", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [
          {
            op: "quote",
            items: [{ type: "amulet", material: "silver", enchantment: 2, cursed: false }],
          },
        ],
      });

      expect(result).toEqual({ results: [{ premium: 71 }] });
    });
    it("a single staff → base premium 80 G", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [
          {
            op: "quote",
            items: [{ type: "staff", material: "oak", enchantment: 1, cursed: false }],
          },
        ],
      });

      expect(result).toEqual({ results: [{ premium: 93 }] });
    });
    it("a single potion → base premium 40 G", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "potion" }] }],
      });

      expect(result).toEqual({ results: [{ premium: 49 }] });
    });
    it("a single rune (component) → base premium 25 G", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "rune" }] }],
      });

      // 25 base + 2.5 first insurance + 5 fee = 32.5 → 33 (rounded in MHPCO's favor)
      expect(result).toEqual({ results: [{ premium: 33 }] });
    });
    it.todo("a single moonstone (component) → base premium 25 G");
  });

  describe("quote — building block of 3 alike components", () => {
    it.todo("2 runes → 50 G base premium");
    it.todo("3 runes → 60 G base premium (block applies)");
    it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
    it.todo("7 runes → 175 G base premium");
    it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
    it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
  });

  describe("quote — premium modifiers", () => {
    it.todo("cursed sword adds a 50 % risk surcharge on the item's base premium");
    it.todo("sword with enchantment 5 adds a 30 % high-enchantment surcharge (threshold inclusive)");
    it.todo("sword with enchantment 4 gets no high-enchantment surcharge");
    it.todo("cursed sword with enchantment 5 gets both surcharges");
    it.todo("customer with exactly 2 years with MHPCO receives the 20 % loyalty discount");
    it.todo("customer with 1 year with MHPCO receives no loyalty discount");
    it.todo("every item in a quote carries the 10 % first insurance surcharge");
    it.todo("the customer's second quote receives an additional 15 % follow-up contract discount");
  });

  describe("quote — modifier scope on multi-item policies", () => {
    it.todo(
      "cursed sword + plain amulet → 210 G before further modifiers and fee (curse applies to the cursed item's base premium only)",
    );
    it.todo("policy-wide modifiers apply to the sum of all item base premiums");
  });

  describe("quote — rounding in the MHPCO's favor", () => {
    it.todo("a premium calculation yielding 197.5 G → final premium 198 G (rounded up)");
    it.todo("intermediate amounts are kept as fractions; only the final premium is rounded");
  });

  describe("quote — integration examples", () => {
    it.todo("newcomer (0 years, no previous contract) with a cursed sword → premium 165 G");
    it.todo("long-standing customer (3 years), second quote, cursed sword enchantment 7 → premium 160 G");
  });

  describe("claim — standard reimbursement", () => {
    it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
    it.todo("damage to a rune (no enchantment, no material), damage 200 G → payout 100 G");
    it.todo("damage below the deductible → payout 0 G");
  });

  describe("claim — special clauses", () => {
    it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % then deductible)");
    it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full then deductible)");
    it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins)");
    it.todo("dragon-material sword, enchantment 8, damage 1000 G → payout 400 G (threshold inclusive)");
  });

  describe("claim — deductible per damage event", () => {
    it.todo("dragon attack damaging a sword (500 G) and an amulet (300 G) → payout 600 G");
  });

  describe("claim — multiple items of the same type", () => {
    it.todo("a policy covering two swords → insurance sum 2000 G, cap 4000 G");
    it.todo("two sword damage entries against two insured swords → each gets its own deductible");
    it.todo("more damage entries of a type than the policy covers → error");
  });

  describe("claim — cap", () => {
    it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
    it.todo("a cursed sword → cap 2000 G (premium modifiers do not raise the cap)");
    it.todo("a policy covering a sword and 3 runes → insurance sum 1750 G (block discount does not affect the sum)");
    it.todo("sword policy (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G");
    it.todo("sword policy, second claim of 1500 G → payout 600 G, remainingCap 0 G (reduced to remaining cap)");
  });

  describe("claim — rounding in the MHPCO's favor", () => {
    it.todo("a payout calculation yielding 350.5 G → final payout 350 G (rounded down)");
  });

  describe("errors", () => {
    it.todo("quote with an item of unknown type (e.g. broomstick) → error");
    it.todo("claim referencing an item that is not part of the policy → error");
    it.todo("claim referencing a damage item with an unknown type → error");
    it.todo("claim with a damage entry of amount -200 → error");
  });

  describe("scenario processing", () => {
    it.todo("results array has the same length and order as the input steps");
    it.todo("a claim step refers to the policy created by an earlier quote step via its zero-based index");
  });
});

