export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: { cause: string; damages: Damage[] };
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export type StepResult =
  | { premium: number }
  | { payout: number; remainingCap: number };

export interface ScenarioResult {
  results: StepResult[];
}

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
const BASE_PREMIUM_RATES: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const COMPONENT_BLOCK_SIZE = 3;
const COMPONENT_BLOCK_PREMIUM = 60;

const countByType = (items: Item[]): Map<string, number> =>
  items.reduce(
    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
    new Map<string, number>(),
  );

const basePremiumForGroup = (type: string, itemCount: number): number =>
  itemCount === COMPONENT_BLOCK_SIZE
    ? COMPONENT_BLOCK_PREMIUM
    : itemCount * BASE_PREMIUM_RATES[type];

const sumBasePremiums = (items: Item[]): number =>
  [...countByType(items)].reduce(
    (sum, [type, itemCount]) => sum + basePremiumForGroup(type, itemCount),
    0,
  );

const quote = (items: Item[]): StepResult => {
  const basePremium = sumBasePremiums(items);
  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;

  return {
    premium: Math.ceil(basePremium + firstInsuranceSurcharge + PROCESSING_FEE),
  };
};

const runStep = (step: Step): StepResult => {
  switch (step.op) {
    case "quote":
      return quote(step.items);
    default:
      throw new Error(`Unsupported step: ${step.op}`);
  }
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map(runStep),
});

