        policy: 0,
        incident: { cause: "fire", damages: [{ itemType: "sword", amount: 200 }] },
      },
    ],
  });

  // insurance sum 1000 + 600 = 1600 → cap 3200; payout 100 leaves 3100
  expect(result.results[1]).toEqual({ payout: 100, remainingCap: 3100 });
});

